<?php if(!isset($usuario,$modulo,$detalle)||($usuario['rol']??'')!=='ADMIN'){http_response_code(403);exit;} $r=$detalle;
$campos=match($modulo){'usuarios'=>['usuario'=>'Nombre de usuario','rol'=>'Rol','nombres'=>'Cliente','cedula'=>'Cédula','estado'=>'Estado','bloqueado'=>'Bloqueo','intentos_fallidos'=>'Intentos fallidos'],'cuentas'=>['numero'=>'Número','nombres'=>'Cliente','cedula'=>'Cédula','tipo'=>'Tipo','saldo'=>'Saldo','estado'=>'Estado'],'tarjetas'=>['codigo_qr'=>'Código QR','numero_cuenta'=>'Cuenta','nombres'=>'Cliente','cedula'=>'Cédula','activa'=>'Estado de tarjeta','cuenta_activa'=>'Estado de cuenta','fecha_emision'=>'Emisión','fecha_anulacion'=>'Anulación'],'movimientos'=>['id'=>'Identificador','nombres'=>'Cliente','cedula'=>'Cédula','numero_cuenta'=>'Cuenta','tipo'=>'Tipo','monto'=>'Monto','fecha'=>'Fecha','cuenta_relacionada'=>'Cuenta relacionada','saldo_resultante'=>'Saldo resultante','referencia'=>'Referencia']};?>
<section class="crud-detalle-seccion"><h2>Detalle del registro</h2><dl class="crud-detalle-grid"><?php foreach($campos as $k=>$label):?><div class="crud-detalle-campo"><dt><?=h($label)?></dt><dd><?php if(in_array($k,['estado','activa','cuenta_activa'],true)):?><?= $k==='activa' ? estado($r[$k],'Vigente','Histórica (inactiva)') : estado($r[$k],in_array($modulo,['cuentas','tarjetas'],true)?'Activa':'Activo',in_array($modulo,['cuentas','tarjetas'],true)?'Inactiva':'Inactivo')?><?php elseif($k==='bloqueado'):?><?=estado(!$r[$k],'No bloqueado','Bloqueado')?><?php elseif(in_array($k,['saldo','monto','saldo_resultante'],true)):?><?=dinero($r[$k])?><?php else:?><?=h($r[$k]??'—')?><?php endif;?></dd></div><?php endforeach;?></dl></section>
<?php if($modulo==='usuarios'):?>
<section class="crud-detalle-seccion"><h2>Gestión de acceso</h2><?php if($r['rol']==='ADMIN'):?><div class="alerta alerta-info">Administrador protegido.</div><?php else:?>
<div class="crud-acciones"><?php accion($r['estado']?'desactivar':'activar',$r['estado']?'Desactivar':'Reactivar',['id'=>$r['id']]);if($r['bloqueado']||$r['intentos_fallidos'])accion('desbloquear','Desbloquear',['id'=>$r['id']]);?></div></section>
<section class="crud-formulario-contenedor"><h2>Restablecer PIN</h2><form method="post" action="<?=h($ruta)?>" class="crud-formulario" onsubmit="return confirm('¿Restablecer el PIN?')"><?=token()?><input type="hidden" name="accion" value="pin"><input type="hidden" name="id" value="<?=h($r['id'])?>"><?php require __DIR__.'/modulo-pin.php';?><button type="submit" class="btn btn-primario">Restablecer PIN</button></form><?php endif;?></section>
<?php elseif($modulo==='cuentas'):?><section class="crud-detalle-seccion"><h2>Gestión de cuenta</h2><p>Para eliminar: saldo cero y sin movimientos.</p><div class="crud-acciones"><?php accion($r['estado']?'desactivar':'activar',$r['estado']?'Desactivar':'Reactivar',['numero'=>$r['numero']]);accion('eliminar','Eliminar cuenta',['numero'=>$r['numero']]);?></div></section>
<?php elseif($modulo==='tarjetas'):?><section class="crud-detalle-seccion"><h2>Estado de la tarjeta</h2><p><?= $r['activa'] && $r['cuenta_activa'] ? 'Tarjeta vigente.' : 'Tarjeta no disponible para operaciones.' ?></p></section><?php endif;?>
